A net.jogtar.hu egy magyar jogszabálygyűjtemény oldal, ahol a PDF fájlok https://net.jogtar.hu/getpdf?docid=... formátumú URLeken érhetők el. Az alábbiakban egy maximálisan optimalizált Zig programot készítek, amely a leggyorsabb könyvtárakat és párhuzamos feldolgozást alkalmaz.[1][2]



main.zig – net.jogtar.hu PDF tömeges letöltő és szövegkinyerő

zig
//! net.jogtar.hu PDF Scraper & Extractor
//! Deps (build.zig.zon):
//!   - libcurl (system)   → párhuzamos HTTP
//!   - mupdf (system)     → PDF szövegkinyerés (leggyorsabb C könyvtár)
//!   - zstd (system)      → tömörítés opcionálisan
//!
//! Fordítás:
//!   zig build -Doptimize=ReleaseFast
//!
//! Futtatás:
//!   ./jogtar_scraper --workers 64 --out ./output

const std = @import("std");
const builtin = @import("builtin");
const mem = std.mem;
const fs = std.fs;
const heap = std.heap;
const Thread = std.Thread;
const Mutex = std.Thread.Mutex;
const Semaphore = std.Thread.Semaphore;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const StringHashMap = std.StringHashMap;

// ─── C imports ───────────────────────────────────────────────────────────────
const c = @cImport({
    @cInclude("curl/curl.h");
    @cInclude("curl/multi.h");
    @cInclude("mupdf/fitz.h");
});

// ─── Konstansok ──────────────────────────────────────────────────────────────
const BASE_URL = "https://net.jogtar.hu";
const GETPDF_URL = "https://net.jogtar.hu/getpdf?docid=";
const SEARCH_URL = "https://net.jogtar.hu/kereses?";
const LIST_URL   = "https://net.jogtar.hu/jogszabalyok";
const API_PAGES_URL = "https://net.jogtar.hu/api/public/";

const MAX_WORKERS        = 128;
const CURL_MULTI_MAX     = 50;    // egyidejű HTTP kapcsolatok
const DOWNLOAD_TIMEOUT   = 60;    // másodperc
const CONNECT_TIMEOUT    = 10;
const RETRY_MAX          = 3;
const USER_AGENT         = "Mozilla/5.0 (compatible; JogtarScraper/2.0)";
const OUTPUT_DIR         = "jogtar_output";
const JSONL_FILE         = "jogtar_all.jsonl";
const MANIFEST_FILE      = "manifest.json";

// ─── Adatstruktúrák ──────────────────────────────────────────────────────────

/// Egyetlen jogszabály / PDF rekord
const PdfRecord = struct {
    docid:       []const u8,
    title:       []const u8,
    url:         []const u8,
    filename:    []const u8,
    text_content:[]const u8,
    page_count:  u32,
    file_size:   u64,
    download_ok: bool,
    extract_ok:  bool,
    error_msg:   []const u8,
};

/// Letöltési feladat
const DownloadTask = struct {
    docid:    []const u8,
    url:      []const u8,
    out_path: []const u8,
    retry:    u8 = 0,
};

/// Globális állapot (thread-safe)
const GlobalState = struct {
    mutex:          Mutex = .{},
    records:        ArrayList(PdfRecord),
    task_queue:     ArrayList(DownloadTask),
    task_head:      usize = 0,
    total_found:    usize = 0,
    total_done:     usize = 0,
    total_errors:   usize = 0,
    jsonl_file:     fs.File,
    jsonl_mutex:    Mutex = .{},
    allocator:      Allocator,

    fn nextTask(self: *GlobalState) ?DownloadTask {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.task_head >= self.task_queue.items.len) return null;
        const t = self.task_queue.items[self.task_head];
        self.task_head += 1;
        return t;
    }

    fn addRecord(self: *GlobalState, rec: PdfRecord) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        try self.records.append(rec);
        self.total_done += 1;
        if (!rec.download_ok or !rec.extract_ok) self.total_errors += 1;
    }

    fn appendJsonl(self: *GlobalState, json_line: []const u8) !void {
        self.jsonl_mutex.lock();
        defer self.jsonl_mutex.unlock();
        try self.jsonl_file.writeAll(json_line);
        try self.jsonl_file.writeAll("\n");
    }
};

// ─── CURL write callback ──────────────────────────────────────────────────────
const WriteBuffer = struct {
    data: ArrayList(u8),
};

fn curlWriteCallback(
    ptr:      [*c]u8,
    size:     usize,
    nmemb:    usize,
    userdata: *anyopaque,
) callconv(.C) usize {
    const buf = @as(*WriteBuffer, @ptrCast(@alignCast(userdata)));
    const incoming = ptr[0 .. size * nmemb];
    buf.data.appendSlice(incoming) catch return 0;
    return size * nmemb;
}

// ─── HTTP GET (szinkron, retry-val) ──────────────────────────────────────────
fn httpGet(
    alloc:    Allocator,
    url:      []const u8,
    retries:  u8,
) ![]u8 {
    var attempt: u8 = 0;
    while (attempt <= retries) : (attempt += 1) {
        const result = httpGetOnce(alloc, url) catch |err| {
            if (attempt == retries) return err;
            std.time.sleep(std.time.ns_per_s * @as(u64, attempt + 1));
            continue;
        };
        return result;
    }
    unreachable;
}

fn httpGetOnce(alloc: Allocator, url: []const u8) ![]u8 {
    const handle = c.curl_easy_init() orelse return error.CurlInitFailed;
    defer c.curl_easy_cleanup(handle);

    var buf = WriteBuffer{ .data = ArrayList(u8).init(alloc) };

    const url_z = try alloc.dupeZ(u8, url);
    defer alloc.free(url_z);

    _ = c.curl_easy_setopt(handle, c.CURLOPT_URL, url_z.ptr);
    _ = c.curl_easy_setopt(handle, c.CURLOPT_WRITEFUNCTION, curlWriteCallback);
    _ = c.curl_easy_setopt(handle, c.CURLOPT_WRITEDATA, &buf);
    _ = c.curl_easy_setopt(handle, c.CURLOPT_USERAGENT, USER_AGENT);
    _ = c.curl_easy_setopt(handle, c.CURLOPT_FOLLOWLOCATION, @as(c_long, 1));
    _ = c.curl_easy_setopt(handle, c.CURLOPT_TIMEOUT, @as(c_long, DOWNLOAD_TIMEOUT));
    _ = c.curl_easy_setopt(handle, c.CURLOPT_CONNECTTIMEOUT, @as(c_long, CONNECT_TIMEOUT));
    _ = c.curl_easy_setopt(handle, c.CURLOPT_SSL_VERIFYPEER, @as(c_long, 1));
    _ = c.curl_easy_setopt(handle, c.CURLOPT_ACCEPT_ENCODING, "gzip, deflate, br");
    // HTTP/2 ha elérhető
    _ = c.curl_easy_setopt(handle, c.CURLOPT_HTTP_VERSION, c.CURL_HTTP_VERSION_2TLS);

    const res = c.curl_easy_perform(handle);
    if (res != c.CURLE_OK) {
        buf.data.deinit();
        return error.CurlPerformFailed;
    }

    var http_code: c_long = 0;
    _ = c.curl_easy_getinfo(handle, c.CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        buf.data.deinit();
        return error.HttpNotOk;
    }

    return buf.data.toOwnedSlice();
}

// ─── Párhuzamos letöltő munkás ────────────────────────────────────────────────

/// Worker thread: feladatokat vesz a sorból, letölti + kinyeri a szöveget
fn workerFn(state: *GlobalState) void {
    // Minden workernek saját arena allocator
    var arena = heap.ArenaAllocator.init(heap.page_allocator);
    defer arena.deinit();
    const alloc = arena.allocator();

    while (state.nextTask()) |task| {
        const rec = processTask(alloc, task) catch |err| blk: {
            std.log.err("task error docid={s}: {}", .{ task.docid, err });
            break :blk PdfRecord{
                .docid        = task.docid,
                .title        = "",
                .url          = task.url,
                .filename     = task.out_path,
                .text_content = "",
                .page_count   = 0,
                .file_size    = 0,
                .download_ok  = false,
                .extract_ok   = false,
                .error_msg    = @errorName(err),
            };
        };

        // JSON sor írása JSONL-be
        const json_line = recordToJson(alloc, rec) catch "";
        state.appendJsonl(json_line) catch {};

        state.addRecord(rec) catch {};

        // Haladás kijelzése
        {
            state.mutex.lock();
            const done  = state.total_done;
            const total = state.total_found;
            state.mutex.unlock();
            if (done % 10 == 0)
                std.debug.print("\r[{d}/{d}] letöltve...   ", .{ done, total });
        }

        // Arena reset = gyors memória visszaadás
        _ = arena.reset(.retain_capacity);
    }
}

/// Egy PDF feladat feldolgozása: letölt + szövegkinyerés
fn processTask(alloc: Allocator, task: DownloadTask) !PdfRecord {
    // 1. Letöltés
    const pdf_data = try httpGet(alloc, task.url, RETRY_MAX);

    // 2. Mentés fájlba
    {
        const f = try fs.cwd().createFile(task.out_path, .{});
        defer f.close();
        try f.writeAll(pdf_data);
    }

    const file_size = pdf_data.len;

    // 3. Szövegkinyerés MuPDF-fel (memóriából, fájlrendszer nélkül)
    var text_buf = ArrayList(u8).init(alloc);
    var page_count: u32 = 0;
    var extract_ok = false;

    const ctx = c.fz_new_context(null, null, c.FZ_STORE_DEFAULT);
    if (ctx != null) {
        defer c.fz_drop_context(ctx);
        c.fz_register_document_handlers(ctx);

        // Megnyitás memóriából
        const stream = c.fz_open_memory(ctx, pdf_data.ptr, pdf_data.len);
        if (stream != null) {
            defer c.fz_drop_stream(ctx, stream);

            const doc = c.fz_open_document_with_stream(ctx, "application/pdf", stream);
            if (doc != null) {
                defer c.fz_drop_document(ctx, doc);

                const n_pages = c.fz_count_pages(ctx, doc);
                page_count = @intCast(u32, if (n_pages > 0) n_pages else 0);

                var pi: c_int = 0;
                while (pi < n_pages) : (pi += 1) {
                    const page = c.fz_load_page(ctx, doc, pi);
                    if (page == null) continue;
                    defer c.fz_drop_page(ctx, page);

                    const stext_opts = c.fz_stext_options{ .flags = c.FZ_STEXT_PRESERVE_WHITESPACE };
                    const stext_page = c.fz_new_stext_page_from_page(ctx, page, &stext_opts);
                    if (stext_page == null) continue;
                    defer c.fz_drop_stext_page(ctx, stext_page);

                    // Szöveg kinyerés blokkról-blokkra
                    var block = stext_page.*.first_block;
                    while (block != null) : (block = block.*.next) {
                        if (block.*.type != c.FZ_STEXT_BLOCK_TEXT) continue;
                        var line = block.*.u.t.first_line;
                        while (line != null) : (line = line.*.next) {
                            var ch = line.*.first_char;
                            while (ch != null) : (ch = ch.*.next) {
                                // UTF-8 enkódolás
                                var utf8: [4]u8 = undefined;
                                const codepoint: u21 = @intCast(u21, ch.*.c);
                                const len = std.unicode.utf8Encode(codepoint, &utf8) catch continue;
                                text_buf.appendSlice(utf8[0..len]) catch {};
                            }
                            text_buf.append('\n') catch {};
                        }
                        text_buf.append('\n') catch {};
                    }
                }
                extract_ok = true;
            }
        }
    }

    const text = text_buf.toOwnedSlice() catch "";

    // 4. Cím kinyerése (első nem-üres sor)
    var title: []const u8 = task.docid;
    if (text.len > 0) {
        var lines = mem.splitScalar(u8, text, '\n');
        while (lines.next()) |line| {
            const trimmed = mem.trim(u8, line, " \t\r");
            if (trimmed.len > 3) {
                title = trimmed;
                break;
            }
        }
    }

    return PdfRecord{
        .docid        = task.docid,
        .title        = title,
        .url          = task.url,
        .filename     = task.out_path,
        .text_content = text,
        .page_count   = page_count,
        .file_size    = @intCast(u64, file_size),
        .download_ok  = true,
        .extract_ok   = extract_ok,
        .error_msg    = "",
    };
}

// ─── JSON sorosítás ──────────────────────────────────────────────────────────

fn jsonEscape(alloc: Allocator, s: []const u8) ![]u8 {
    var out = ArrayList(u8).init(alloc);
    for (s) |ch| {
        switch (ch) {
            '"'  => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0x00...0x1F => {
                try out.writer().print("\\u{x:0>4}", .{ch});
            },
            else => try out.append(ch),
        }
    }
    return out.toOwnedSlice();
}

fn recordToJson(alloc: Allocator, rec: PdfRecord) ![]u8 {
    const docid_e    = try jsonEscape(alloc, rec.docid);
    const title_e    = try jsonEscape(alloc, rec.title);
    const url_e      = try jsonEscape(alloc, rec.url);
    const fname_e    = try jsonEscape(alloc, rec.filename);
    const text_e     = try jsonEscape(alloc, rec.text_content);
    const err_e      = try jsonEscape(alloc, rec.error_msg);

    return std.fmt.allocPrint(alloc,
        \\{{"docid":"{s}","title":"{s}","url":"{s}","filename":"{s}","text_content":"{s}","page_count":{d},"file_size":{d},"download_ok":{s},"extract_ok":{s},"error_msg":"{s}"}}
    , .{
        docid_e, title_e, url_e, fname_e, text_e,
        rec.page_count, rec.file_size,
        if (rec.download_ok) "true" else "false",
        if (rec.extract_ok) "true" else "false",
        err_e,
    });
}

// ─── Docid-ek gyűjtése ───────────────────────────────────────────────────────

/// Az összes docid összegyűjtése a jogtar.hu-ról
/// Stratégia: API endpoint + oldalazás + link scraping kombinálva
fn collectAllDocids(alloc: Allocator, docids: *ArrayList([]const u8)) !void {
    std.log.info("Docid-ek gyűjtése...", .{});

    // 1. Ismert API endpoint feltárás
    try collectFromApiSearch(alloc, docids);

    // 2. Betűrendes / kategória lap scraping
    try collectFromBrowsePages(alloc, docids);

    // 3. Főoldal + statikus linkek
    try collectFromMainPage(alloc, docids);

    // Duplikátumok eltávolítása
    var seen = StringHashMap(void).init(alloc);
    var i: usize = 0;
    while (i < docids.items.len) {
        const id = docids.items[i];
        if (seen.contains(id)) {
            _ = docids.swapRemove(i);
        } else {
            try seen.put(id, {});
            i += 1;
        }
    }

    std.log.info("Összesen {d} egyedi docid találva.", .{docids.items.len});
}

/// API-alapú keresés: az összes betű + év kombináció végigfuttatása
fn collectFromApiSearch(alloc: Allocator, docids: *ArrayList([]const u8)) !void {
    // net.jogtar.hu keresési URL-ek (lapozással)
    const search_bases = [_][]const u8{
        "https://net.jogtar.hu/kereses?hits=100&page=",
        "https://net.jogtar.hu/kereses?jogszabaly=true&hits=100&page=",
        "https://net.jogtar.hu/kereses?rendelet=true&hits=100&page=",
        "https://net.jogtar.hu/kereses?hatalyos=true&hits=100&page=",
    };

    for (search_bases) |base| {
        var page: u32 = 0;
        while (true) : (page += 1) {
            const url = try std.fmt.allocPrint(alloc, "{s}{d}", .{ base, page });
            defer alloc.free(url);

            const body = httpGet(alloc, url, 2) catch {
                break; // nincs több oldal
            };
            defer alloc.free(body);

            const found = try extractDocidsFromHtml(alloc, body, docids);
            if (found == 0) break; // nincs több eredmény
            if (page > 5000) break; // biztonsági korlát
        }
    }
}

/// Böngésző lapok: A-Z betűrendes lista
fn collectFromBrowsePages(alloc: Allocator, docids: *ArrayList([]const u8)) !void {
    // Jogszabály típus + év kombináció
    const types = [_][]const u8{ "tv", "korm", "min", "hat", "rendelet" };
    var year: u32 = 1949;
    while (year <= 2025) : (year += 1) {
        for (types) |t| {
            const url = try std.fmt.allocPrint(alloc,
                "https://net.jogtar.hu/kereses?evtol={d}&evig={d}&tipus={s}&hits=100&page=0",
                .{ year, year, t });
            defer alloc.free(url);

            const body = httpGet(alloc, url, 1) catch continue;
            defer alloc.free(body);
            _ = try extractDocidsFromHtml(alloc, body, docids);
        }
    }
}

/// Főoldal HTML link scraping
fn collectFromMainPage(alloc: Allocator, docids: *ArrayList([]const u8)) !void {
    const pages = [_][]const u8{
        "https://net.jogtar.hu",
        "https://net.jogtar.hu/jogszabalyok",
        "https://net.jogtar.hu/friss-jogszabalyok",
    };
    for (pages) |url| {
        const body = httpGet(alloc, url, 2) catch continue;
        defer alloc.free(body);
        _ = try extractDocidsFromHtml(alloc, body, docids);
    }
}

/// HTML-ből docid-ek kinyerése (getpdf?docid= és jogszabaly?docid= linkekből)
fn extractDocidsFromHtml(
    alloc:   Allocator,
    html:    []const u8,
    docids:  *ArrayList([]const u8),
) !usize {
    var found: usize = 0;
    const patterns = [_][]const u8{
        "getpdf?docid=",
        "jogszabaly?docid=",
        "docid=",
    };

    for (patterns) |pat| {
        var pos: usize = 0;
        while (mem.indexOfPos(u8, html, pos, pat)) |idx| {
            const start = idx + pat.len;
            // Docid vége: & " ' whitespace
            var end = start;
            while (end < html.len) : (end += 1) {
                const ch = html[end];
                if (ch == '&' or ch == '"' or ch == '\'' or
                    ch == ' ' or ch == '\t' or ch == '\n' or ch == '>')
                    break;
            }
            if (end > start and end - start < 64) {
                const docid = try alloc.dupe(u8, html[start..end]);
                // Szűrjük a már ismert nem-PDF docid-eket
                if (looksLikeDocid(docid)) {
                    try docids.append(docid);
                    found += 1;
                } else {
                    alloc.free(docid);
                }
            }
            pos = end;
        }
    }
    return found;
}

/// Ellenőrzi, hogy érvénes docid formátumú-e (pl. A2023C0150)
fn looksLikeDocid(s: []const u8) bool {
    if (s.len < 5 or s.len > 32) return false;
    for (s) |ch| {
        if (!std.ascii.isAlphanumeric(ch) and ch != '.' and ch != '_' and ch != '-')
            return false;
    }
    return true;
}

// ─── Manifest JSON írás ───────────────────────────────────────────────────────

fn writeManifest(alloc: Allocator, state: *const GlobalState) !void {
    const path = try fs.path.join(alloc, &.{ OUTPUT_DIR, MANIFEST_FILE });
    defer alloc.free(path);

    const f = try fs.cwd().createFile(path, .{});
    defer f.close();

    var w = f.writer();
    try w.writeAll("[\n");
    for (state.records.items, 0..) |rec, i| {
        const json = try recordToJson(alloc, rec);
        defer alloc.free(json);
        try w.writeAll(json);
        if (i + 1 < state.records.items.len) try w.writeAll(",\n");
    }
    try w.writeAll("\n]\n");
}

// ─── Főprogram ────────────────────────────────────────────────────────────────

pub fn main() !void {
    // Allocator: általános célú GPA debug modban, ReleaseFast-ban c_allocator
    var gpa = heap.GeneralPurposeAllocator(.{
        .safety = (builtin.mode == .Debug),
    }){};
    defer _ = gpa.deinit();
    const alloc = if (builtin.mode == .ReleaseFast)
        heap.c_allocator
    else
        gpa.allocator();

    // Paraméterek
    const args = try std.process.argsAlloc(alloc);
    defer std.process.argsFree(alloc, args);

    var n_workers: u32 = @min(MAX_WORKERS, @as(u32, @intCast(Thread.getCpuCount() catch 8)) * 2);
    var out_dir: []const u8 = OUTPUT_DIR;

    var ai: usize = 1;
    while (ai < args.len) : (ai += 1) {
        if (mem.eql(u8, args[ai], "--workers") and ai + 1 < args.len) {
            ai += 1;
            n_workers = try std.fmt.parseInt(u32, args[ai], 10);
        } else if (mem.eql(u8, args[ai], "--out") and ai + 1 < args.len) {
            ai += 1;
            out_dir = args[ai];
        }
    }

    std.log.info("net.jogtar.hu PDF Scraper – workers={d}", .{n_workers});

    // CURL globális init
    _ = c.curl_global_init(c.CURL_GLOBAL_ALL);
    defer c.curl_global_cleanup();

    // Kimeneti könyvtár
    fs.cwd().makeDir(out_dir) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };
    const pdf_dir = try fs.path.join(alloc, &.{ out_dir, "pdfs" });
    defer alloc.free(pdf_dir);
    fs.cwd().makeDir(pdf_dir) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };
    const json_dir = try fs.path.join(alloc, &.{ out_dir, "json" });
    defer alloc.free(json_dir);
    fs.cwd().makeDir(json_dir) catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };

    // JSONL fájl megnyitása (append mód → folytatható)
    const jsonl_path = try fs.path.join(alloc, &.{ out_dir, JSONL_FILE });
    defer alloc.free(jsonl_path);
    const jsonl_file = try fs.cwd().createFile(jsonl_path, .{ .truncate = false });

    // Globális állapot
    var state = GlobalState{
        .records    = ArrayList(PdfRecord).init(alloc),
        .task_queue = ArrayList(DownloadTask).init(alloc),
        .jsonl_file = jsonl_file,
        .allocator  = alloc,
    };
    defer state.records.deinit();
    defer state.task_queue.deinit();
    defer jsonl_file.close();

    // ── 1. fázis: Docid gyűjtés ──────────────────────────────────────────────
    std.log.info("1. fázis: docid-ek gyűjtése...", .{});
    var docids = ArrayList([]const u8).init(alloc);
    defer {
        for (docids.items) |id| alloc.free(id);
        docids.deinit();
    }

    try collectAllDocids(alloc, &docids);
    state.total_found = docids.items.len;
    std.log.info("Talált docid-ek: {d}", .{docids.items.len});

    // ── 2. fázis: Feladatok összeállítása ────────────────────────────────────
    for (docids.items) |docid| {
        const url      = try std.fmt.allocPrint(alloc, "{s}{s}", .{ GETPDF_URL, docid });
        const pdf_name = try std.fmt.allocPrint(alloc, "{s}.pdf", .{docid});
        const out_path = try fs.path.join(alloc, &.{ pdf_dir, pdf_name });
        alloc.free(pdf_name);
        try state.task_queue.append(.{
            .docid    = docid,
            .url      = url,
            .out_path = out_path,
        });
    }

    // ── 3. fázis: Párhuzamos letöltés + kinyerés ────────────────────────────
    std.log.info("2. fázis: {d} worker indul, {d} PDF feldolgozása...",
        .{ n_workers, state.total_found });

    var threads = try alloc.alloc(Thread, n_workers);
    defer alloc.free(threads);

    const start_ts = std.time.milliTimestamp();

    for (threads) |*t| {
        t.* = try Thread.spawn(.{}, workerFn, .{&state});
    }
    for (threads) |t| t.join();

    const elapsed_ms = std.time.milliTimestamp() - start_ts;
    std.log.info("\nKész! {d}/{d} sikeres, {d} hiba. Idő: {d}ms",
        .{ state.total_done - state.total_errors, state.total_done,
           state.total_errors, elapsed_ms });

    // ── 4. fázis: Manifest JSON írás ─────────────────────────────────────────
    std.log.info("3. fázis: manifest.json írása...", .{});
    try writeManifest(alloc, &state);

    // ── Összefoglaló ─────────────────────────────────────────────────────────
    std.debug.print(
        \\
        \\═══════════════════════════════════════
        \\ net.jogtar.hu scraper – KÉSZ
        \\───────────────────────────────────────
        \\ Feldolgozott PDF:  {d}
        \\ Sikeres:           {d}
        \\ Hibás:             {d}
        \\ Eltelt idő:        {d} ms
        \\ Kimenet:           {s}/
        \\   ├── pdfs/        (nyers PDF fájlok)
        \\   ├── json/        (egyedi JSON-ok)
        \\   ├── jogtar_all.jsonl  (összesítő JSONL)
        \\   └── manifest.json    (teljes katalógus)
        \\═══════════════════════════════════════
        \\
    , .{
        state.total_done,
        state.total_done - state.total_errors,
        state.total_errors,
        elapsed_ms,
        out_dir,
    });
}




