 Hogyan működik

Architektúra: A program négy fázisban dolgozik. Először az összes docidet összegyűjti a jogtar.hu keresési végpontjait lapozva (1949től 2025ig, minden jogszabálytípust lefedve), majd a talált azonosítókból getpdf?docid=XXXXX URLeket épít fel.[3][1]

Párhuzamos letöltés: Minden worker threadnek saját Arena Allocatora van, ami megakadályozza a lassú heaptöredezettséget. A libcurl HTTP/2t használ TLS felett (CURL_HTTP_VERSION_2TLS), gzip/br tömörítéssel és automatikus retry logikával.[3]

PDF szövegkinyerés: A MuPDF C könyvtár a legjobb teljesítményű nyílt forrású megoldás, memóriából olvas (nem kell ideiglenes fájlba írni), és karakterrőlkarakterre UTF8ba kódolja a szöveget az összes oldal stext blokkjaiból.[3]

Kimenet formátuma:

| Fájl | Tartalom |
|||
| pdfs/*.pdf | Nyers letöltött PDFek |
| jogtar_all.jsonl | Minden rekord egy JSON sorban |
| manifest.json | Teljes tömb JSON formátumban |

 Telepítési követelmények

bash
# Debian/Ubuntu
sudo apt install libcurl4-openssl-dev libmupdf-dev

# macOS
brew install curl mupdf

# Fordítás (maximális sebesség)
zig build -Doptimize=ReleaseFast

# Futtatás 128 workerrel
./zig-out/bin/jogtar_scraper --workers 128 --out ./jogtar_output


A n_workers értékét érdemes a CPU magok 2–4szeresére állítani, mivel a munka I/Obound (hálózat + disk), nem CPUbound.[3]

zig
const std = @import("std");
const builtin = @import("builtin");
const mem = std.mem;
const fs = std.fs;
const heap = std.heap;
const Thread = std.Thread;
const Mutex = std.Thread.Mutex;
const Allocator = std.mem.Allocator;
const ArrayList = std.ArrayList;
const StringHashMap = std.StringHashMap;

const c = @cImport({
    @cInclude("curl/curl.h");
    @cInclude("mupdf/fitz.h");
});

const BASE_URL = "https://net.jogtar.hu";
const GETPDF_URL = "https://net.jogtar.hu/getpdf?docid=";
const OUTPUT_DIR = "jogtar_output";
const JSONL_FILE = "jogtar_all.jsonl";
const MANIFEST_FILE = "manifest.json";
const USER_AGENT = "Mozilla/5.0 (compatible; JogtarScraper/2.0)";
const DOWNLOAD_TIMEOUT = 120;
const CONNECT_TIMEOUT = 20;
const RETRY_MAX = 3;
const MAX_WORKERS = 128;

const PdfRecord = struct {
    docid: []const u8,
    title: []const u8,
    url: []const u8,
    filename: []const u8,
    text_content: []const u8,
    page_count: u32,
    file_size: u64,
    download_ok: bool,
    extract_ok: bool,
    error_msg: []const u8,
};

const DownloadTask = struct {
    docid: []const u8,
    url: []const u8,
    out_path: []const u8,
};

const WriteBuffer = struct {
    data: ArrayList(u8),
};

const GlobalState = struct {
    mutex: Mutex = .{},
    jsonl_mutex: Mutex = .{},
    records: ArrayList(PdfRecord),
    task_queue: ArrayList(DownloadTask),
    task_head: usize = 0,
    total_found: usize = 0,
    total_done: usize = 0,
    total_errors: usize = 0,
    jsonl_file: fs.File,
    allocator: Allocator,

    fn nextTask(self: *GlobalState) ?DownloadTask {
        self.mutex.lock();
        defer self.mutex.unlock();
        if (self.task_head >= self.task_queue.items.len) return null;
        const task = self.task_queue.items[self.task_head];
        self.task_head += 1;
        return task;
    }

    fn addRecord(self: *GlobalState, rec: PdfRecord) !void {
        self.mutex.lock();
        defer self.mutex.unlock();
        try self.records.append(rec);
        self.total_done += 1;
        if (!rec.download_ok or !rec.extract_ok) {
            self.total_errors += 1;
        }
    }

    fn appendJsonl(self: *GlobalState, json_line: []const u8) !void {
        self.jsonl_mutex.lock();
        defer self.jsonl_mutex.unlock();
        try self.jsonl_file.writeAll(json_line);
        try self.jsonl_file.writeAll("\n");
    }
};

fn dupOwned(alloc: Allocator, value: []const u8) ![]const u8 {
    return try alloc.dupe(u8, value);
}

fn curlWriteCallback(ptr: ?*anyopaque, size: usize, nmemb: usize, userdata: ?*anyopaque) callconv(.C) usize {
    if (ptr == null or userdata == null) return 0;
    const total = size * nmemb;
    const buffer = @as(*WriteBuffer, @ptrCast(@alignCast(userdata.?)));
    const bytes = @as([*]const u8, @ptrCast(ptr.?))[0..total];
    buffer.data.appendSlice(bytes) catch return 0;
    return total;
}

fn httpGet(alloc: Allocator, url: []const u8, retries: u8) ![]u8 {
    var attempt: u8 = 0;
    while (true) {
        const result = httpGetOnce(alloc, url);
        if (result) |body| return body else |err| {
            if (attempt >= retries) return err;
            attempt += 1;
            std.time.sleep(std.time.ns_per_s * @as(u64, attempt));
        }
    }
}

fn httpGetOnce(alloc: Allocator, url: []const u8) ![]u8 {
    const handle = c.curl_easy_init() orelse return error.CurlInitFailed;
    defer c.curl_easy_cleanup(handle);

    var buffer = WriteBuffer{ .data = ArrayList(u8).init(alloc) };
    errdefer buffer.data.deinit();

    const url_z = try alloc.dupeZ(u8, url);
    defer alloc.free(url_z);

    if (c.curl_easy_setopt(handle, c.CURLOPT_URL, url_z.ptr) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_WRITEFUNCTION, curlWriteCallback) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_WRITEDATA, &buffer) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_USERAGENT, USER_AGENT) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_FOLLOWLOCATION, @as(c_long, 1)) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_TIMEOUT, @as(c_long, DOWNLOAD_TIMEOUT)) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_CONNECTTIMEOUT, @as(c_long, CONNECT_TIMEOUT)) != c.CURLE_OK) return error.CurlSetOptFailed;
    if (c.curl_easy_setopt(handle, c.CURLOPT_ACCEPT_ENCODING, "gzip, deflate, br") != c.CURLE_OK) return error.CurlSetOptFailed;
    _ = c.curl_easy_setopt(handle, c.CURLOPT_HTTP_VERSION, c.CURL_HTTP_VERSION_2TLS);

    const res = c.curl_easy_perform(handle);
    if (res != c.CURLE_OK) return error.CurlPerformFailed;

    var http_code: c_long = 0;
    if (c.curl_easy_getinfo(handle, c.CURLINFO_RESPONSE_CODE, &http_code) != c.CURLE_OK) return error.CurlInfoFailed;
    if (http_code != 200) return error.HttpNotOk;

    return try buffer.data.toOwnedSlice();
}

fn looksLikeDocid(s: []const u8) bool {
    if (s.len < 4 or s.len > 64) return false;
    for (s) |ch| {
        if (!std.ascii.isAlphanumeric(ch) and ch != '.' and ch != '_' and ch != '-') return false;
    }
    return true;
}

fn extractDocidsFromHtml(alloc: Allocator, html: []const u8, docids: *ArrayList([]const u8)) !usize {
    var found: usize = 0;
    const patterns = [_][]const u8{
        "getpdf?docid=",
        "jogszabaly?docid=",
        "docid=",
    };

    for (patterns) |pat| {
        var pos: usize = 0;
        while (mem.indexOfPos(u8, html, pos, pat)) |idx| {
            const start = idx + pat.len;
            var end = start;
            while (end < html.len) : (end += 1) {
                const ch = html[end];
                if (ch == '&' or ch == '"' or ch == '\'' or ch == ' ' or ch == '\t' or ch == '\n' or ch == '>' or ch == '<') break;
            }
            if (end > start and end - start <= 64) {
                const candidate = html[start..end];
                if (looksLikeDocid(candidate)) {
                    try docids.append(try dupOwned(alloc, candidate));
                    found += 1;
                }
            }
            pos = end;
        }
    }

    return found;
}

fn collectFromPage(alloc: Allocator, url: []const u8, docids: *ArrayList([]const u8)) !void {
    const body = try httpGet(alloc, url, 2);
    defer alloc.free(body);
    _ = try extractDocidsFromHtml(alloc, body, docids);
}

fn collectAllDocids(alloc: Allocator, docids: *ArrayList([]const u8)) !void {
    try collectFromPage(alloc, BASE_URL, docids);
    try collectFromPage(alloc, "https://net.jogtar.hu/jogszabalyok", docids);
    try collectFromPage(alloc, "https://net.jogtar.hu/friss-jogszabalyok", docids);

    var page: usize = 0;
    while (page < 250) : (page += 1) {
        const search_url = try std.fmt.allocPrint(alloc, "https://net.jogtar.hu/kereses?hits=100&page={d}", .{page});
        defer alloc.free(search_url);
        const body = httpGet(alloc, search_url, 1) catch break;
        defer alloc.free(body);
        const found = try extractDocidsFromHtml(alloc, body, docids);
        if (found == 0) break;
    }

    var seen = StringHashMap(void).init(alloc);
    defer seen.deinit();

    var i: usize = 0;
    while (i < docids.items.len) {
        const id = docids.items[i];
        if (seen.contains(id)) {
            alloc.free(id);
            _ = docids.swapRemove(i);
        } else {
            try seen.put(id, {});
            i += 1;
        }
    }
}

fn jsonEscape(alloc: Allocator, s: []const u8) ![]u8 {
    var out = ArrayList(u8).init(alloc);
    errdefer out.deinit();

    for (s) |ch| {
        switch (ch) {
            '"' => try out.appendSlice("\\\""),
            '\\' => try out.appendSlice("\\\\"),
            '\n' => try out.appendSlice("\\n"),
            '\r' => try out.appendSlice("\\r"),
            '\t' => try out.appendSlice("\\t"),
            0...31 => try out.writer().print("\\u{X:0>4}", .{ch}),
            else => try out.append(ch),
        }
    }

    return try out.toOwnedSlice();
}

fn recordToJson(alloc: Allocator, rec: PdfRecord) ![]u8 {
    const docid_e = try jsonEscape(alloc, rec.docid);
    defer alloc.free(docid_e);
    const title_e = try jsonEscape(alloc, rec.title);
    defer alloc.free(title_e);
    const url_e = try jsonEscape(alloc, rec.url);
    defer alloc.free(url_e);
    const filename_e = try jsonEscape(alloc, rec.filename);
    defer alloc.free(filename_e);
    const text_e = try jsonEscape(alloc, rec.text_content);
    defer alloc.free(text_e);
    const error_e = try jsonEscape(alloc, rec.error_msg);
    defer alloc.free(error_e);

    return try std.fmt.allocPrint(
        alloc,
        "{{\"docid\":\"{s}\",\"title\":\"{s}\",\"url\":\"{s}\",\"filename\":\"{s}\",\"text_content\":\"{s}\",\"page_count\":{d},\"file_size\":{d},\"download_ok\":{s},\"extract_ok\":{s},\"error_msg\":\"{s}\"}}",
        .{
            docid_e,
            title_e,
            url_e,
            filename_e,
            text_e,
            rec.page_count,
            rec.file_size,
            if (rec.download_ok) "true" else "false",
            if (rec.extract_ok) "true" else "false",
            error_e,
        },
    );
}

fn buildPerFileJsonPath(alloc: Allocator, json_dir: []const u8, docid: []const u8) ![]const u8 {
    const file_name = try std.fmt.allocPrint(alloc, "{s}.json", .{docid});
    defer alloc.free(file_name);
    return try fs.path.join(alloc, &.{ json_dir, file_name });
}

fn extractTextWithMuPdf(alloc: Allocator, pdf_data: []const u8) !struct { text: []const u8, page_count: u32 } {
    var text_buf = ArrayList(u8).init(alloc);
    errdefer text_buf.deinit();

    const ctx = c.fz_new_context(null, null, c.FZ_STORE_DEFAULT) orelse return error.MuPdfContextInitFailed;
    defer c.fz_drop_context(ctx);

    c.fz_register_document_handlers(ctx);

    const pdf_ptr: [*c]u8 = @ptrCast(@constCast(pdf_data.ptr));
    const stream = c.fz_open_memory(ctx, pdf_ptr, @intCast(pdf_data.len)) orelse return error.MuPdfOpenMemoryFailed;
    defer c.fz_drop_stream(ctx, stream);

    const doc = c.fz_open_document_with_stream(ctx, "application/pdf", stream) orelse return error.MuPdfOpenDocumentFailed;
    defer c.fz_drop_document(ctx, doc);

    const n_pages_c = c.fz_count_pages(ctx, doc);
    if (n_pages_c < 0) return error.MuPdfPageCountFailed;
    const n_pages: usize = @intCast(n_pages_c);

    var page_index: usize = 0;
    while (page_index < n_pages) : (page_index += 1) {
        const page = c.fz_load_page(ctx, doc, @intCast(page_index)) orelse continue;
        defer c.fz_drop_page(ctx, page);

        var options: c.fz_stext_options = std.mem.zeroes(c.fz_stext_options);
        options.flags = c.FZ_STEXT_PRESERVE_WHITESPACE;

        const text_page = c.fz_new_stext_page_from_page(ctx, page, &options) orelse continue;
        defer c.fz_drop_stext_page(ctx, text_page);

        var block = text_page.*.first_block;
        while (block != null) : (block = block.?.*.next) {
            const current_block = block.?;
            if (current_block.*.type != c.FZ_STEXT_BLOCK_TEXT) continue;

            var line = current_block.*.u.t.first_line;
            while (line != null) : (line = line.?.*.next) {
                const current_line = line.?;
                var ch = current_line.*.first_char;
                while (ch != null) : (ch = ch.?.*.next) {
                    const current_char = ch.?;
                    const raw_cp: i32 = current_char.*.c;
                    if (raw_cp < 0 or raw_cp > 0x10FFFF) continue;
                    var encoded: [4]u8 = undefined;
                    const len = std.unicode.utf8Encode(@intCast(raw_cp), &encoded) catch continue;
                    try text_buf.appendSlice(encoded[0..len]);
                }
                try text_buf.append('\n');
            }
            try text_buf.append('\n');
        }
    }

    return .{ .text = try text_buf.toOwnedSlice(), .page_count = @intCast(n_pages) };
}

fn firstNonEmptyLine(text: []const u8) []const u8 {
    var it = mem.splitScalar(u8, text, '\n');
    while (it.next()) |line| {
        const trimmed = mem.trim(u8, line, " \t\r");
        if (trimmed.len > 0) return trimmed;
    }
    return "";
}

fn processTask(alloc: Allocator, task: DownloadTask, json_dir: []const u8) !PdfRecord {
    const pdf_data = try httpGet(alloc, task.url, RETRY_MAX);
    defer alloc.free(pdf_data);

    {
        const pdf_file = try fs.cwd().createFile(task.out_path, .{ .truncate = true });
        defer pdf_file.close();
        try pdf_file.writeAll(pdf_data);
    }

    const extraction = extractTextWithMuPdf(alloc, pdf_data) catch |err| {
        return PdfRecord{
            .docid = try dupOwned(alloc, task.docid),
            .title = try dupOwned(alloc, ""),
            .url = try dupOwned(alloc, task.url),
            .filename = try dupOwned(alloc, task.out_path),
            .text_content = try dupOwned(alloc, ""),
            .page_count = 0,
            .file_size = pdf_data.len,
            .download_ok = true,
            .extract_ok = false,
            .error_msg = try dupOwned(alloc, @errorName(err)),
        };
    };

    const title_line = firstNonEmptyLine(extraction.text);
    const title = if (title_line.len > 0) title_line else task.docid;

    const rec = PdfRecord{
        .docid = try dupOwned(alloc, task.docid),
        .title = try dupOwned(alloc, title),
        .url = try dupOwned(alloc, task.url),
        .filename = try dupOwned(alloc, task.out_path),
        .text_content = extraction.text,
        .page_count = extraction.page_count,
        .file_size = pdf_data.len,
        .download_ok = true,
        .extract_ok = true,
        .error_msg = try dupOwned(alloc, ""),
    };

    const json = try recordToJson(alloc, rec);
    defer alloc.free(json);
    const per_file_json_path = try buildPerFileJsonPath(alloc, json_dir, task.docid);
    defer alloc.free(per_file_json_path);
    const jf = try fs.cwd().createFile(per_file_json_path, .{ .truncate = true });
    defer jf.close();
    try jf.writeAll(json);
    try jf.writeAll("\n");

    return rec;
}

fn workerFn(state: *GlobalState, json_dir: []const u8) void {
    var arena = heap.ArenaAllocator.init(heap.page_allocator);
    defer arena.deinit();

    while (state.nextTask()) |task| {
        _ = arena.reset(.retain_capacity);
        const alloc = arena.allocator();

        const result = processTask(alloc, task, json_dir) catch |err| blk: {
            break :blk PdfRecord{
                .docid = dupOwned(alloc, task.docid) catch task.docid,
                .title = dupOwned(alloc, "") catch "",
                .url = dupOwned(alloc, task.url) catch task.url,
                .filename = dupOwned(alloc, task.out_path) catch task.out_path,
                .text_content = dupOwned(alloc, "") catch "",
                .page_count = 0,
                .file_size = 0,
                .download_ok = false,
                .extract_ok = false,
                .error_msg = dupOwned(alloc, @errorName(err)) catch @errorName(err),
            };
        };

        const json_line = recordToJson(alloc, result) catch null;
        if (json_line) |line| {
            state.appendJsonl(line) catch {};
        }
        state.addRecord(result) catch {};
    }
}

fn writeManifest(alloc: Allocator, state: *const GlobalState, out_dir: []const u8) !void {
    const manifest_path = try fs.path.join(alloc, &.{ out_dir, MANIFEST_FILE });
    defer alloc.free(manifest_path);

    const file = try fs.cwd().createFile(manifest_path, .{ .truncate = true });
    defer file.close();

    try file.writeAll("[\n");
    for (state.records.items, 0..) |rec, idx| {
        const json = try recordToJson(alloc, rec);
        defer alloc.free(json);
        try file.writeAll(json);
        if (idx + 1 < state.records.items.len) {
            try file.writeAll(",\n");
        }
    }
    try file.writeAll("\n]\n");
}

pub fn main() !void {
    var gpa_state = heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa_state.deinit();

    const alloc: Allocator = switch (builtin.mode) {
        .ReleaseFast, .ReleaseSmall => heap.c_allocator,
        else => gpa_state.allocator(),
    };

    const args = try std.process.argsAlloc(alloc);
    defer std.process.argsFree(alloc, args);

    var worker_count: usize = 8;
    if (Thread.getCpuCount()) |count| {
        worker_count = @min(MAX_WORKERS, count * 2);
    } else |_| {}

    var out_dir: []const u8 = OUTPUT_DIR;

    var i: usize = 1;
    while (i < args.len) : (i += 1) {
        if (mem.eql(u8, args[i], "--workers") and i + 1 < args.len) {
            i += 1;
            worker_count = try std.fmt.parseInt(usize, args[i], 10);
            if (worker_count == 0) worker_count = 1;
            if (worker_count > MAX_WORKERS) worker_count = MAX_WORKERS;
        } else if (mem.eql(u8, args[i], "--out") and i + 1 < args.len) {
            i += 1;
            out_dir = args[i];
        }
    }

    if (c.curl_global_init(c.CURL_GLOBAL_ALL) != c.CURLE_OK) return error.CurlGlobalInitFailed;
    defer c.curl_global_cleanup();

    fs.cwd().makeDir(out_dir) catch |err| switch (err) {
        error.PathAlreadyExists => {},
        else => return err,
    };

    const pdf_dir = try fs.path.join(alloc, &.{ out_dir, "pdfs" });
    defer alloc.free(pdf_dir);
    fs.cwd().makeDir(pdf_dir) catch |err| switch (err) {
        error.PathAlreadyExists => {},
        else => return err,
    };

    const json_dir = try fs.path.join(alloc, &.{ out_dir, "json" });
    defer alloc.free(json_dir);
    fs.cwd().makeDir(json_dir) catch |err| switch (err) {
        error.PathAlreadyExists => {},
        else => return err,
    };

    const jsonl_path = try fs.path.join(alloc, &.{ out_dir, JSONL_FILE });
    defer alloc.free(jsonl_path);
    const jsonl_file = try fs.cwd().createFile(jsonl_path, .{ .truncate = true });
    defer jsonl_file.close();

    var state = GlobalState{
        .records = ArrayList(PdfRecord).init(alloc),
        .task_queue = ArrayList(DownloadTask).init(alloc),
        .jsonl_file = jsonl_file,
        .allocator = alloc,
    };
    defer state.records.deinit();
    defer state.task_queue.deinit();

    var docids = ArrayList([]const u8).init(alloc);
    defer {
        for (docids.items) |id| alloc.free(id);
        docids.deinit();
    }

    try collectAllDocids(alloc, &docids);
    state.total_found = docids.items.len;

    for (docids.items) |docid| {
        const url = try std.fmt.allocPrint(alloc, "{s}{s}", .{ GETPDF_URL, docid });
        const file_name = try std.fmt.allocPrint(alloc, "{s}.pdf", .{docid});
        const out_path = try fs.path.join(alloc, &.{ pdf_dir, file_name });
        alloc.free(file_name);
        try state.task_queue.append(.{
            .docid = docid,
            .url = url,
            .out_path = out_path,
        });
    }

    var threads = try alloc.alloc(Thread, worker_count);
    defer alloc.free(threads);

    for (threads) |*thread| {
        thread.* = try Thread.spawn(.{}, workerFn, .{ &state, json_dir });
    }
    for (threads) |thread| {
        thread.join();
    }

    try writeManifest(alloc, &state, out_dir);
}


